/* eslint-disable @typescript-eslint/naming-convention */
import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { ApplicationConfig } from 'espd-common/config';
import {
	Observable,
	of,
	Subject
} from 'rxjs';
import { filter, map, share, take, tap } from 'rxjs/operators';

export enum SettingType {
	SESSION_DURATION_SECONDS = 'common.SESSION_DURATION_SECONDS',
	CUSTOM_FOOTER = 'common.CUSTOM_FOOTER',
	CUSTOM_HEADER = 'common.CUSTOM_HEADER',
	LOGO_URL = 'common.LOGO_URL',
	LOGO_URL_MOBILE = 'common.LOGO_URL_MOBILE',
	LOGO_DISPLAY = 'common.LOGO_DISPLAY'
}

@Injectable()
export abstract class SettingService {

	protected settings: { [key: string]: any } = {};
	private loadedModules: Array<string> = [];

	private dataUpdateSubject: Subject<string> = new Subject();
	// eslint-disable-next-line @typescript-eslint/member-ordering
	public readonly onDataUpdate: Observable<string> = this.dataUpdateSubject.asObservable();

	constructor(private http: HttpClient, private config: ApplicationConfig) { }

	public init(module: string): any {
		const obs = this.http.get(`${this.config.settingsPath}?module=${module}`)
			.pipe(
				tap((data: any) => {
					Object.assign(this.settings, data);
					this.initializeSettings(module);
				}),
				share()
			);
		obs.subscribe(() => {
			this.loadedModules.push(module);
			this.dataUpdateSubject.next(module);
		});
		return obs;
	}

	//public get(key: SettingType): any {
	public get(key: string): any {
		return this.settings[key];
	}

	public waitFor(...modules: string[]): Observable<void> {
		if (this.loadedModules.some(item => modules.includes(item))) {
			return of(void 0);
		} else {
			return this.onDataUpdate.pipe(filter(m => modules.includes(m)), take(1), map(() => void 0));
		}
	}

	/** A method to allow parsing or modifying of the setting data after it is retrieved, but before it is released to subscribers. */
	public abstract initializeSettings(module: string): void;
}